```js
#!/usr/bin/env node
const args = process.argv.slice(2);
// parse --upper and --repeat <N>
let upper = false;
let repeat = 1;
let text = "";
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === "--upper") { upper = true; continue; }
  if (a === "--repeat") {
    const n = args[++i];
    if (n === undefined || !/^\d+$/.test(n)) {
      console.error("usage: cli.js --upper [--repeat N] <text>");
      process.exit(1);
    }
    repeat = Number(n);
    continue;
  }
  if (a.startsWith("-")) {
    console.error("usage: cli.js --upper [--repeat N] <text>");
    process.exit(1);
  }
  text = a;
}
if (!text) {
  console.error("usage: cli.js --upper [--repeat N] <text>");
  process.exit(1);
}
const out = upper ? text.toUpperCase() : text;
for (let i = 0; i < repeat; i++) console.log(out);
```

