function run(args) {
  try {
    return { stdout: execFileSync(process.execPath, [CLI, ...args], { encoding: "utf8" }), code: 0 };
  } catch (e) {
    return { stdout: e.stdout || "", stderr: e.stderr || "", code: e.status };
  }
}

test("upper-cases a single argument by default", () => {
  const { stdout, code } = run(["--upper", "hello"]);
  assert.equal(code, 0);
  assert.equal(stdout.trim(), "HELLO");
});

test("--repeat N prints the output N times, one per line", () => {
  const { stdout, code } = run(["--upper", "--repeat", "3", "hi"]);
  assert.equal(code, 0);
  const lines = stdout.trim().split("\n");
  assert.equal(lines.length, 3);
  assert.ok(lines.every((l) => l === "HI"));
});

test("--repeat 0 prints nothing", () => {
  const { stdout, code } = run(["--upper", "--repeat", "0", "hi"]);
  assert.equal(code, 0);
  assert.equal(stdout, "");
});

test("non-integer repeat count is a usage error", () => {
  const { code, stderr } = run(["--upper", "--repeat", "abc", "hi"]);
  assert.equal(code, 1);
  assert.match(stderr, /usage:/);
});

test("empty-string repeat value is a usage error", () => {
  const { code, stderr } = run(["--upper", "--repeat", "", "hi"]);
  assert.equal(code, 1);
  assert.match(stderr, /usage:/);
});

test("empty text is a usage error", () => {
  const { code, stderr } = run(["--upper", "--repeat", "3", ""]);
  assert.equal(code, 1);
  assert.match(stderr, /usage:/);
});

test("without --upper, --repeat applies to the raw text", () => {
  const { stdout, code } = run(["--repeat", "2", "hi"]);
  assert.equal(code, 0);
  assert.equal(stdout.trim().split("\n").join(" "), "hi hi");
});

test("missing text is a usage error", () => {
  const { code } = run(["--upper"]);
  assert.equal(code, 1);
});

